from itertools import combinations
from typing import List

Square = List[List[int]]

def is_latin(sq: Square, n: int) -> bool:
    """Check the row and column permutation conditions. Complexity: O(n^2)."""
    S = set(range(n))
    if any(set(sq[i]) != S for i in range(n)):
        return False
    return all({sq[i][j] for i in range(n)} == S for j in range(n))

def is_orthogonal(a: Square, b: Square, n: int) -> bool:
    """Check that the n^2 superposed pairs are distinct. Complexity: O(n^2)."""
    return len({(a[i][j], b[i][j]) for i in range(n) for j in range(n)}) == n * n

def is_mols(family: List[Square], n: int) -> bool:
    """Verify a family is MOLS. Complexity: O(k^2 * n^2)."""
    if not all(is_latin(sq, n) for sq in family):
        return False
    return all(is_orthogonal(a, b, n) for a, b in combinations(family, 2))
